DROP TABLE IF EXISTS `md_supplier_qualification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_supplier_qualification` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `supplier_id` bigint NOT NULL,
  `qual_name` varchar(100) NOT NULL COMMENT '证照名称(营业执照/开户许可/行业资质...)',
  `qual_no` varchar(100) DEFAULT NULL COMMENT '证照编号',
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL COMMENT '有效期至(到期预警依据)',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_msq_supplier` (`supplier_id`),
  KEY `idx_msq_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=700000050 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商资质证照(N)';
